/// Whether the matrix permits `rel` from `source` to `target`.
///
/// This is the table lookup only. Archi layers two further rules on
/// top: no duplicate direct relationship of the same type between the
/// same ordered pair, and every relationship touching a junction must
/// be of the same type, checked transitively through it.
#[inline]
pub fn allows(source: u8, target: u8, rel: RelType) -> bool {
    let (s, t) = (source as usize, target as usize);
    if s >= CONCEPTS || t >= CONCEPTS {
        return false;
    }
    MATRIX[s * CONCEPTS + t] & (1 << rel as u16) != 0
}

/// Every relationship type the matrix permits between this pair.
pub fn permitted(source: u8, target: u8) -> Vec<RelType> {
    RelType::ALL.into_iter().filter(|r| allows(source, target, *r)).collect()
}
